create extension if not exists pgcrypto;

create type public.campaign_status as enum ('DRAFT','ACTIVE','PAUSED','CLOSED','CANCELLED');
create type public.draw_status as enum ('DRAFT','SCHEDULED','EXECUTED','CANCELLED');
create type public.order_status as enum ('PENDING_PAYMENT','PAYMENT_SUBMITTED','PAYMENT_VERIFIED','TICKETS_ISSUED','CANCELLED','REFUNDED');
create type public.payment_method as enum ('MANUAL_UPI');
create type public.payment_status as enum ('PENDING','SUBMITTED','VERIFIED','FAILED','REFUNDED','CANCELLED');
create type public.ticket_status as enum ('RESERVED','ISSUED','VOID','REFUNDED');

create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade, full_name text not null, phone text,
  email text, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.roles (id uuid primary key default gen_random_uuid(), name text not null unique check (name in ('SUPER_ADMIN','ADMIN','FUNDRAISING_MANAGER','SELLER')));
create table public.profile_roles (profile_id uuid not null references public.profiles(id) on delete cascade, role_id uuid not null references public.roles(id) on delete restrict, created_at timestamptz not null default now(), primary key (profile_id,role_id));
create table public.campaigns (
 id uuid primary key default gen_random_uuid(), public_id text not null unique check (public_id ~ '^[a-z0-9-]+$'), name text not null, description text,
 ticket_price_paise integer not null check(ticket_price_paise > 0), currency text not null default 'INR' check(currency='INR'), total_ticket_limit integer not null check(total_ticket_limit > 0), sold_ticket_count integer not null default 0 check(sold_ticket_count >= 0 and sold_ticket_count <= total_ticket_limit), status public.campaign_status not null default 'DRAFT', start_at timestamptz, end_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(end_at is null or start_at is null or end_at > start_at)
);
create table public.prizes (id uuid primary key default gen_random_uuid(), campaign_id uuid not null references public.campaigns(id) on delete cascade, prize_number smallint not null check(prize_number > 0), title text not null, description text, cash_amount_paise integer check(cash_amount_paise is null or cash_amount_paise >= 0), display_order smallint not null check(display_order > 0), created_at timestamptz not null default now(), unique(campaign_id,prize_number), unique(campaign_id,display_order));
create table public.draws (id uuid primary key default gen_random_uuid(), campaign_id uuid not null references public.campaigns(id) on delete restrict, name text not null, status public.draw_status not null default 'DRAFT', scheduled_at timestamptz, executed_at timestamptz, created_at timestamptz not null default now());
create table public.customers (id uuid primary key default gen_random_uuid(), profile_id uuid unique references public.profiles(id) on delete set null, full_name text not null, phone text not null, whatsapp_number text, email text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.sellers (id uuid primary key default gen_random_uuid(), profile_id uuid not null unique references public.profiles(id) on delete restrict, seller_code text not null unique check(seller_code ~ '^SELLER-[0-9]{3,}$'), display_name text not null, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.orders (id uuid primary key default gen_random_uuid(), order_number text not null unique check(order_number ~ '^ORD-[0-9]{4}-[0-9]{6}$'), campaign_id uuid not null references public.campaigns(id) on delete restrict, customer_id uuid not null references public.customers(id) on delete restrict, seller_id uuid references public.sellers(id) on delete set null, quantity integer not null check(quantity between 1 and 1000), unit_price_paise integer not null check(unit_price_paise > 0), total_amount_paise integer not null check(total_amount_paise = quantity * unit_price_paise), status public.order_status not null default 'PENDING_PAYMENT', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, quantity integer not null check(quantity > 0), unit_price_paise integer not null check(unit_price_paise > 0), total_amount_paise integer not null check(total_amount_paise = quantity * unit_price_paise), created_at timestamptz not null default now());
create table public.payments (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete restrict, payment_method public.payment_method not null default 'MANUAL_UPI', status public.payment_status not null default 'PENDING', amount_paise integer not null check(amount_paise > 0), currency text not null default 'INR' check(currency='INR'), utr_reference text, payer_name text, submitted_at timestamptz, verified_at timestamptz, verified_by uuid references public.profiles(id) on delete set null, rejection_reason text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check((status in ('PENDING','CANCELLED') and submitted_at is null) or (status in ('SUBMITTED','VERIFIED','FAILED','REFUNDED') and submitted_at is not null)), check(status <> 'VERIFIED' or (verified_at is not null and verified_by is not null)));
create table public.payment_events (id uuid primary key default gen_random_uuid(), payment_id uuid not null references public.payments(id) on delete restrict, event_type text not null, old_status public.payment_status, new_status public.payment_status, metadata jsonb not null default '{}'::jsonb, created_by uuid references public.profiles(id) on delete set null, created_at timestamptz not null default now());
create table public.tickets (id uuid primary key default gen_random_uuid(), campaign_id uuid not null references public.campaigns(id) on delete restrict, order_id uuid not null references public.orders(id) on delete restrict, order_item_id uuid references public.order_items(id) on delete set null, customer_id uuid not null references public.customers(id) on delete restrict, seller_id uuid references public.sellers(id) on delete set null, ticket_number text not null unique check(ticket_number ~ '^SSFI-[0-9]{6}$'), status public.ticket_status not null default 'ISSUED', issued_at timestamptz not null default now(), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.draw_results (id uuid primary key default gen_random_uuid(), draw_id uuid not null references public.draws(id) on delete restrict, prize_id uuid not null references public.prizes(id) on delete restrict, ticket_id uuid not null references public.tickets(id) on delete restrict, created_at timestamptz not null default now(), unique(draw_id,prize_id), unique(draw_id,ticket_id));
create table public.ticket_verifications (id uuid primary key default gen_random_uuid(), ticket_id uuid not null references public.tickets(id) on delete restrict, verified_at timestamptz not null default now(), verification_source text not null, ip_hash text, user_agent text, created_at timestamptz not null default now());
create table public.audit_logs (id uuid primary key default gen_random_uuid(), actor_user_id uuid references public.profiles(id) on delete set null, action text not null, entity_type text not null, entity_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create sequence public.ssfi_ticket_number_sequence minvalue 1 maxvalue 1000 no cycle;

create index orders_customer_idx on public.orders(customer_id); create index orders_seller_idx on public.orders(seller_id); create index payments_utr_idx on public.payments(utr_reference) where utr_reference is not null; create index payments_order_idx on public.payments(order_id); create index tickets_campaign_idx on public.tickets(campaign_id); create index tickets_order_idx on public.tickets(order_id); create index payment_events_payment_idx on public.payment_events(payment_id); create index verifications_ticket_idx on public.ticket_verifications(ticket_id);

create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create trigger profiles_updated before update on public.profiles for each row execute function public.set_updated_at(); create trigger campaigns_updated before update on public.campaigns for each row execute function public.set_updated_at(); create trigger customers_updated before update on public.customers for each row execute function public.set_updated_at(); create trigger sellers_updated before update on public.sellers for each row execute function public.set_updated_at(); create trigger orders_updated before update on public.orders for each row execute function public.set_updated_at(); create trigger payments_updated before update on public.payments for each row execute function public.set_updated_at(); create trigger tickets_updated before update on public.tickets for each row execute function public.set_updated_at();

create or replace function public.has_role(p_user_id uuid, p_role text) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profile_roles pr join roles r on r.id=pr.role_id where pr.profile_id=p_user_id and r.name=p_role) $$;
create or replace function public.is_staff(p_user_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select public.has_role(p_user_id,'SUPER_ADMIN') or public.has_role(p_user_id,'ADMIN') or public.has_role(p_user_id,'FUNDRAISING_MANAGER') $$;
create or replace function public.current_seller_id() returns uuid language sql stable security definer set search_path=public as $$ select id from sellers where profile_id=auth.uid() and is_active limit 1 $$;
create or replace function public.owns_customer(p_customer_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from customers where id=p_customer_id and profile_id=auth.uid()) $$;
create or replace function public.seller_owns_customer(p_customer_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from orders where customer_id=p_customer_id and seller_id=public.current_seller_id()) $$;
revoke all on function public.has_role(uuid,text), public.is_staff(uuid), public.current_seller_id(), public.owns_customer(uuid), public.seller_owns_customer(uuid) from public; grant execute on function public.has_role(uuid,text), public.is_staff(uuid), public.current_seller_id(), public.owns_customer(uuid), public.seller_owns_customer(uuid) to authenticated;

create or replace function public.validate_status_transition() returns trigger language plpgsql as $$ begin
 if tg_table_name='payments' and old.status<>new.status and not ((old.status='PENDING' and new.status in ('SUBMITTED','CANCELLED')) or (old.status='SUBMITTED' and new.status in ('VERIFIED','FAILED','CANCELLED')) or (old.status='VERIFIED' and new.status='REFUNDED')) then raise exception 'invalid payment status transition'; end if;
 if tg_table_name='orders' and old.status<>new.status and not ((old.status='PENDING_PAYMENT' and new.status in ('PAYMENT_SUBMITTED','CANCELLED')) or (old.status='PAYMENT_SUBMITTED' and new.status in ('PAYMENT_VERIFIED','CANCELLED')) or (old.status='PAYMENT_VERIFIED' and new.status in ('TICKETS_ISSUED','REFUNDED','CANCELLED'))) then raise exception 'invalid order status transition'; end if; return new; end $$;
create trigger payment_status_guard before update on public.payments for each row execute function public.validate_status_transition(); create trigger order_status_guard before update on public.orders for each row execute function public.validate_status_transition();
create or replace function public.record_payment_event() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into payment_events(payment_id,event_type,old_status,new_status,created_by) values(new.id,case when tg_op='INSERT' then 'PAYMENT_CREATED' else 'PAYMENT_'||new.status::text end,case when tg_op='INSERT' then null else old.status end,new.status,auth.uid()); return new; end $$;
create trigger payment_event_log after insert or update of status on public.payments for each row execute function public.record_payment_event();

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,phone,email) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',split_part(coalesce(new.email,''),'@',1),'Member'),new.phone,new.email); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();

create or replace function public.issue_tickets(p_order_id uuid) returns setof public.tickets language plpgsql security definer set search_path=public as $$
declare v_order public.orders; v_campaign public.campaigns; v_count integer; v_number integer;
begin
 select * into v_order from orders where id=p_order_id for update; if not found then raise exception 'order not found'; end if;
 if not exists(select 1 from payments where order_id=p_order_id and status='VERIFIED' and amount_paise=v_order.total_amount_paise) then raise exception 'verified payment required'; end if;
 if v_order.status not in ('PAYMENT_VERIFIED') then raise exception 'order is not eligible for issuance'; end if;
 select * into v_campaign from campaigns where id=v_order.campaign_id for update; if not found or v_campaign.status<>'ACTIVE' then raise exception 'campaign is not active'; end if;
 if v_campaign.sold_ticket_count+v_order.quantity>v_campaign.total_ticket_limit then raise exception 'campaign ticket limit exceeded'; end if;
 for v_count in 1..v_order.quantity loop
   v_number:=nextval('public.ssfi_ticket_number_sequence');
   insert into tickets(campaign_id,order_id,customer_id,seller_id,ticket_number,status) values(v_order.campaign_id,v_order.id,v_order.customer_id,v_order.seller_id,format('SSFI-%s',lpad(v_number::text,6,'0')),'ISSUED');
 end loop;
 update campaigns set sold_ticket_count=sold_ticket_count+v_order.quantity where id=v_campaign.id;
 update orders set status='TICKETS_ISSUED' where id=v_order.id;
 insert into audit_logs(actor_user_id,action,entity_type,entity_id,metadata) values(auth.uid(),'TICKET_ISSUED','order',v_order.id,jsonb_build_object('quantity',v_order.quantity));
 return query select * from tickets where order_id=v_order.id order by ticket_number;
end $$;
revoke all on function public.issue_tickets(uuid) from public, anon, authenticated; grant execute on function public.issue_tickets(uuid) to service_role;

alter table public.profiles enable row level security; alter table public.roles enable row level security; alter table public.profile_roles enable row level security; alter table public.campaigns enable row level security; alter table public.prizes enable row level security; alter table public.draws enable row level security; alter table public.draw_results enable row level security; alter table public.customers enable row level security; alter table public.sellers enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.payments enable row level security; alter table public.payment_events enable row level security; alter table public.tickets enable row level security; alter table public.ticket_verifications enable row level security; alter table public.audit_logs enable row level security;
create policy profiles_own_select on public.profiles for select to authenticated using(id=auth.uid() or public.is_staff(auth.uid())); create policy profiles_staff_write on public.profiles for all to authenticated using(public.is_staff(auth.uid())) with check(public.is_staff(auth.uid()));
create policy roles_staff_read on public.roles for select to authenticated using(public.is_staff(auth.uid())); create policy profile_roles_staff_read on public.profile_roles for select to authenticated using(public.is_staff(auth.uid()));
create policy campaigns_public_read on public.campaigns for select using(status='ACTIVE' or public.is_staff(auth.uid())); create policy campaigns_staff_write on public.campaigns for all to authenticated using(public.is_staff(auth.uid())) with check(public.is_staff(auth.uid()));
create policy prizes_public_read on public.prizes for select using(exists(select 1 from campaigns c where c.id=campaign_id and (c.status='ACTIVE' or public.is_staff(auth.uid())))); create policy prizes_staff_write on public.prizes for all to authenticated using(public.is_staff(auth.uid())) with check(public.is_staff(auth.uid()));
create policy draws_staff_access on public.draws for all to authenticated using(public.is_staff(auth.uid())) with check(public.is_staff(auth.uid())); create policy results_staff_access on public.draw_results for all to authenticated using(public.is_staff(auth.uid())) with check(public.is_staff(auth.uid()));
create policy customers_access on public.customers for select to authenticated using(public.owns_customer(id) or public.seller_owns_customer(id) or public.is_staff(auth.uid())); create policy sellers_access on public.sellers for select to authenticated using(profile_id=auth.uid() or public.is_staff(auth.uid()));
create policy orders_access on public.orders for select to authenticated using(public.owns_customer(customer_id) or seller_id=public.current_seller_id() or public.is_staff(auth.uid())); create policy order_items_access on public.order_items for select to authenticated using(order_id in(select id from orders));
create policy payments_access on public.payments for select to authenticated using(order_id in(select id from orders)); create policy tickets_access on public.tickets for select to authenticated using(order_id in(select id from orders));
create policy payment_events_staff_read on public.payment_events for select to authenticated using(public.is_staff(auth.uid())); create policy verification_staff_read on public.ticket_verifications for select to authenticated using(public.is_staff(auth.uid())); create policy audit_staff_read on public.audit_logs for select to authenticated using(public.is_staff(auth.uid()));
revoke insert,update,delete on public.audit_logs, public.payment_events from anon, authenticated;

insert into public.roles(name) values ('SUPER_ADMIN'),('ADMIN'),('FUNDRAISING_MANAGER'),('SELLER') on conflict(name) do nothing;
insert into public.campaigns(public_id,name,description,ticket_price_paise,currency,total_ticket_limit,status) values ('ssfi-fundraising-lucky-draw','SSFI Fundraising Lucky Draw','Fundraising lucky draw for Senthang Students Fellowship India.',10000,'INR',1000,'DRAFT') on conflict(public_id) do nothing;
insert into public.prizes(campaign_id,prize_number,title,description,cash_amount_paise,display_order) select c.id,v.n,v.title,v.description,v.cash,v.n from public.campaigns c cross join (values (1,'1st Prize — ₹10,000 Cash','Cash prize',1000000),(2,'2nd Prize — ₹8,000 Cash','Cash prize',800000),(3,'3rd Prize — Electric Induction','Electric induction cooktop',null::integer),(4,'4th Prize — Ukulele','Ukulele',null::integer),(5,'5th Prize — Mini Soundbox','Mini soundbox',null::integer)) as v(n,title,description,cash) where c.public_id='ssfi-fundraising-lucky-draw' on conflict(campaign_id,prize_number) do nothing;
